185	export function removeAllBlockagesForIssue(
186	  deps: DependenciesFile,
187	  issueId: IssueId,
188	): DependenciesFile {
189	  let newBlockedBy = { ...deps.blockedBy };
190	  let newBlocks = { ...deps.blocks };
191	
192	  // 1. For each entry in blockedBy[issueId] (issue was blocked):
193	  //    remove counterpart from blocks[entry.blockerId]
194	  const blockedByEntries = deps.blockedBy[issueId];
195	  if (blockedByEntries) {
196	    for (const entry of blockedByEntries) {
197	      const blockerBlocks = newBlocks[entry.blockerId];
198	      if (blockerBlocks) {
199	        const filtered = blockerBlocks.filter(
200	          (e) => !(e.blockerId === entry.blockerId && e.blockedId === entry.blockedId),
201	        );
202	        if (filtered.length === 0) {
203	          const { [entry.blockerId]: _, ...rest } = newBlocks;
204	          newBlocks = rest;
205	        } else {
206	          newBlocks = { ...newBlocks, [entry.blockerId]: filtered };
207	        }
208	      }
209	    }
210	    // Delete blockedBy[issueId]
211	    const { [issueId]: _, ...restBlockedBy } = newBlockedBy;
212	    newBlockedBy = restBlockedBy;
213	  }
214	
215	  // 2. For each entry in blocks[issueId] (issue was blocker):
216	  //    remove counterpart from blockedBy[entry.blockedId]
217	  const blocksEntries = deps.blocks[issueId];
218	  if (blocksEntries) {
219	    for (const entry of blocksEntries) {
220	      const blockedBlockedBy = newBlockedBy[entry.blockedId];
221	      if (blockedBlockedBy) {
222	        const filtered = blockedBlockedBy.filter(
223	          (e) => !(e.blockerId === issueId && e.blockedId === entry.blockedId),
224	        );
225	        if (filtered.length === 0) {
226	          const { [entry.blockedId]: _, ...rest } = newBlockedBy;
227	          newBlockedBy = rest;
228	        } else {
229	          newBlockedBy = { ...newBlockedBy, [entry.blockedId]: filtered };
230	        }
231	      }
232	    }
233	    // Delete blocks[issueId]
234	    const { [issueId]: _, ...restBlocks } = newBlocks;
235	    newBlocks = restBlocks;
236	  }
237	
238	  // 3. Clean up empty arrays
239	  for (const key of Object.keys(newBlockedBy)) {
240	    if (newBlockedBy[key]!.length === 0) {
241	      const { [key]: _, ...rest } = newBlockedBy;
242	      newBlockedBy = rest;
243	    }
244	  }
245	  for (const key of Object.keys(newBlocks)) {
246	    if (newBlocks[key]!.length === 0) {
247	      const { [key]: _, ...rest } = newBlocks;
248	      newBlocks = rest;
249	    }
250	  }
251	
252	  return { blockedBy: newBlockedBy, blocks: newBlocks };
253	}
